package com.mst.services;import com.mst.models.dto.SaleOutwardGatePassRequest;import com.mst.repositories.SaleOutwardGatePassRepository;import com.mst.security.CurrentUserContext;import java.time.LocalDate;import java.util.*;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;
@Service public class SaleOutwardGatePassService{private final SaleOutwardGatePassRepository r;private final CurrentUserContext c;public SaleOutwardGatePassService(SaleOutwardGatePassRepository r,CurrentUserContext c){this.r=r;this.c=c;}public Object initial(){return r.initial(c.requireAccountingUser(),c.currentFinancialYearId());}public Object typeCode(String t){return Map.of("code",r.typeCode(c.requireAccountingUser(),c.currentFinancialYearId(),t));}public Object reference(int t,int n,LocalDate d){return r.reference(c.requireAccountingUser(),c.currentFinancialYearId(),t,n,d);}public Object history(){return r.history(c.requireAccountingUser(),c.currentFinancialYearId());}public Object record(int id){return r.record(c.requireAccountingUser(),id);}@Transactional public Object save(SaleOutwardGatePassRequest x){return r.save(c.requireAccountingUser(),c.currentFinancialYearId(),x);}}
